reference_solution:
def minimum_extra_string_characters(s,dictionary):
    words=set(dictionary);dp=[0]*(len(s)+1)
    for end in range(1,len(s)+1):
        dp[end]=dp[end-1]+1
        for start in range(end):
            if s[start:end] in words:dp[end]=min(dp[end],dp[start])
    return dp[-1]

